`timescale 1ns / 1ps

/*-------------------------------------------------------------------------------------------------
 --
 -- File Name         : display_controller.v 
 -- Description       : This module generates display controller and sync information for display.
 -- Targeted device   : Microchip FPGAs                    
 -- Author            : India Solutions Team
 --
 -- COPYRIGHT 2022 BY MICROCHIP 
 -- THE INFORMATION CONTAINED IN THIS DOCUMENT IS SUBJECT TO LICENSING RESTRICTIONS 
 -- FROM MICROSEMI CORP.  IF YOU ARE NOT IN POSSESSION OF WRITTEN AUTHORIZATION FROM 
 -- MICROSEMI FOR USE OF THIS FILE, THEN THE FILE SHOULD BE IMMEDIATELY DESTROYED AND 
 -- NO BACK-UP OF THE FILE SHOULD BE MADE. 
 -- 
 -------------------------------------------------------------------------------------------------*/
module Display_Controller
	# (
		parameter	g_VIDEO_TIMINGS = 0 , // -- 0 -> Predefined timings	
		//-- 1 -> Configurable
		//Video resolution selection
		parameter g_VIDEO_RESOLUTION =4 , //-- 0 -> 1280x720 
		//-- 1 -> 1920x1080 
		//-- 2 -> 3840x2160 
		//-- 3 -> 640x360
		//-- 4 -> 720x480
		//-- 5 -> USER DEFINED
		//--- Pixel data Width
		parameter g_PIXELS_DATA_WIDTH = 24, //--   8 -> "  8" Pixel data width 
		//--  16 -> " 16" Pixel data width 
		//--  24 -> " 24" Pixel data width 
		//--  32 -> " 32" Pixel data width 
		//--  40 -> " 40" Pixel data width 
		//--  48 -> " 48" Pixel data width 
		//--  56 -> " 56" Pixel data width 
		//--  64 -> " 64" Pixel data width 
		//--  72 -> " 72" Pixel data width 
		//--  80 -> " 80" Pixel data width 
		//--  88 -> " 88" Pixel data width 
		//--  96 -> " 96" Pixel data width 
		//-- 104 -> "104" Pixel data width 
		//-- 112 -> "112" Pixel data width 
		//-- 120 -> "120" Pixel data width 
		//--- Pixel per clock
		parameter g_PIXELS_PER_CLK = 1 , //-- 1 -> "1" Pixel per clock 
		//-- 4 -> "4" Pixel per clock 
	
		//--- Pixel per clock
		parameter g_ENABLE_EXT_SYNC = 0 , //-- 1 -> Enables the EXT_SYNC_SIGNAL 
		//        which needs to connect from the last module just before Display controller flow
		//-- 0 -> Disables the EXT_SYNC_SIGNAL
	
		parameter g_CONFIGURATION_INTERFACE = 0 , //-- 1 -> Enables the AXI4 Lite configuration interface 
		//-- 0 -> Disables the AXI4 Lite interface
	
		parameter g_HSYNC_POLARITY =0 ,
		parameter g_VSYNC_POLARITY =0 ,
		parameter g_STROBE_EN =0 ,
		//--- Selecting for Native Format or AXI Based Format
		parameter g_AXI4STREAM_INTERFACE = 0 ,  //-- 0 -> Display_Controller_Native 
		//-- 1 -> Display_Controller with AXI	
		// parameter g_HSYNC_width = g_PIXELS_PER_CLK == 1 ? 1: (g_PIXELS_PER_CLK==4 && g_VIDEO_RESOLUTION ==0 && g_CONFIGURATION_INTERFACE==0) || (g_STROBE_EN == 1 && ) ? 3: 1 ,// 1 -> for 1 pixel mode 1
		parameter g_HSYNC_width = g_PIXELS_PER_CLK == 1 ? 1: g_STROBE_EN == 1 ? 3 :1,
		// 3 -> 4 pixel mode 
		parameter g_VIDEO_DISPLAY_METHOD = 0 // 0 -> for Progressive mode
			// 1 -> Interlaced Mode	
	) 
   (
		// Clock and Reset interface----------------------------------------------------
		input				 AXI4L_CLK_I, // clock
		input				 AXI4L_RESETN_I, // This active-low reset
		//write address channel
		input				 awvalid, // AXI4-Lite write address valid. This signal indicates that valid write address and control information are available.
		output				 awready, // AXI4-Lite write address ready. This signal indicates that the target is ready to accept an address and associated control signals.
		input [31:0]		awaddr, // AXI4-Lite write address.
		//write data channel
		input [31:0]		wdata, // AXI4-Lite write data.
		input				wvalid, // AXI4-Lite write valid.
		output				wready, // AXI4-Lite Write ready.
		//write response channel
		output [1:0]		bresp, // AXI4-Lite write response.
		output				bvalid, // AXI4-Lite write response valid.
		input				bready, // AXI4-Lite response ready.
		//read address channel
		input [31:0]		araddr, // AXI4-Lite read address. The read address gives the address of the first transfer in a read burst transaction.  
		input				arvalid, // AXI4-Lite read address valid. This signal indicates that the channel is signaling valid read address and control information. 
		output				arready, // AXI4-Lite response ready. This signal indicates that the slave is ready to accept an address and associated control signals.
		//read data and response channel
		input				rready, 
		output [31:0]		rdata, // AXI4-Lite read data.
		output [1:0]		rresp, // AXI4-Lite read response.
		output				rvalid, // AXI4-Lite read valid. This signal indicates that the channel is signaling the required read data.
  
		// input Declaration 
		input				 					SYS_CLK_I,
		input				 					RESETN_I,
		input				 					ENABLE_I,
		input				 					EXT_SYNC_SIGNAL_I,
		input	[15:0]			     			H_RESOLUTION_I, 
		input	[15:0]			     			V_RESOLUTION_I, 
		input	[15:0]			     			H_F_PORCH_I, 
		input	[15:0]			     			H_B_PORCH_I, 
		input	[15:0]			     			V_F_PORCH_I, 
		input	[15:0]			     			V_F_PORCH_I1, 
		input	[15:0]			     			V_F_PORCH_I2, 
		input	[15:0]			     			V_B_PORCH_I, 
		input	[15:0]			     			V_B_PORCH_I1, 
		input	[15:0]			     			V_B_PORCH_I2, 
		input	[15:0]			     			H_SYNC_WIDTH_I, 
		input	[15:0]			     			V_SYNC_WIDTH_I, 
		input	[15:0]			     			V_SYNC_WIDTH_I1, 
		input	[15:0]			     			V_SYNC_WIDTH_I2, 
		input	[g_PIXELS_DATA_WIDTH - 1 : 0]	DATA_I, 
		input				 					TVALID_I,
		input	[g_PIXELS_DATA_WIDTH - 1 : 0]	TDATA_I, 
		// output Declaration 	
		output				 					TREADY_O,
		output	[g_HSYNC_width-1:0]				H_SYNC_O, 
		output				 					V_SYNC_O,
		output	[g_HSYNC_width-1:0]				DATA_TRIGGER_O,
		output				 					FRAME_END_O,
		output	[g_HSYNC_width-1:0]				DATA_VALID_O,
		output				 					V_ACTIVE_O,
		output				 					FIELD_O,
		output				 					TLAST_O,
		output				 					TVALID_O,
		output [15:0]			 				V_RES_O,
		output [15:0]			 				H_RES_O, 
		output [g_PIXELS_DATA_WIDTH - 1 : 0] 	TDATA_O,
		output [2:0]			 				TSTRB_O, 
		output [2:0]			 				TKEEP_O, 
		output [3:0]			 				TUSER_O,
		output [g_PIXELS_DATA_WIDTH - 1 : 0] 	DATA_O
    );
   
